import { createHash } from "node:crypto";
import { readFile, readdir, writeFile } from "node:fs/promises";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const scriptDir = dirname(fileURLToPath(import.meta.url));
const repositoryRoot = resolve(scriptDir, "..");
const sourceRoot = join(repositoryRoot, "supabase/functions/_shared/ai");
const outputPath = join(sourceRoot, "promptBundle.generated.ts");
const version = "2026.07.27.1";

const normalize = (value) => value.replace(/\r\n/g, "\n").trimEnd() + "\n";
const sha256 = (value) => createHash("sha256").update(value, "utf8").digest("hex");

async function readText(path) {
  return normalize(await readFile(path, "utf8"));
}

async function readPromptSources() {
  const names = (await readdir(join(sourceRoot, "prompts")))
    .filter((name) => name.endsWith(".md"))
    .sort();
  return Object.fromEntries(await Promise.all(names.map(async (name) => {
    const stage = name.replace(/\.md$/, "");
    const content = await readText(join(sourceRoot, "prompts", name));
    return [stage, { content, hash: sha256(content) }];
  })));
}

async function readPolicySources() {
  const names = (await readdir(join(sourceRoot, "policies")))
    .filter((name) => name.endsWith(".json"))
    .sort();
  return Object.fromEntries(await Promise.all(names.map(async (name) => {
    const key = name.replace(/\.json$/, "");
    const raw = await readText(join(sourceRoot, "policies", name));
    return [key, { value: JSON.parse(raw), hash: sha256(raw) }];
  })));
}

export async function generatePromptBundleSource() {
  const policyContent = await readText(join(sourceRoot, "concept-ai-policy.md"));
  const prompts = await readPromptSources();
  const policies = await readPolicySources();
  const hashInput = JSON.stringify({
    version,
    policy: { content: policyContent, hash: sha256(policyContent) },
    prompts,
    policies,
  });
  const bundle = {
    version,
    hash: sha256(hashInput),
    policy: { content: policyContent, hash: sha256(policyContent) },
    prompts,
    policies,
  };

  return normalize(`// Generated by ${relative(repositoryRoot, fileURLToPath(import.meta.url))}.
// Edit the Markdown/JSON sources and run npm run prompts:build.
export const promptBundle = ${JSON.stringify(bundle, null, 2)} as const;
`);
}

async function main() {
  const generated = await generatePromptBundleSource();
  if (process.argv.includes("--check")) {
    const current = await readFile(outputPath, "utf8").catch(() => "");
    if (normalize(current) !== generated) {
      console.error("Generated prompt bundle is stale. Run npm run prompts:build.");
      process.exitCode = 1;
      return;
    }
    return;
  }
  await writeFile(outputPath, generated, "utf8");
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  await main();
}
